def fig(id,w=495):return Image(str(ROOT/'previews'/f'{id}.png'),width=w,height=w*880/1200)
def table(rows,widths,header=True):
 rows=[[p(str(x),'SmallAC') for x in row] for row in rows]
 t=Table(rows,colWidths=widths,repeatRows=1 if header else 0,hAlign='LEFT')
 t.setStyle(TableStyle([('VALIGN',(0,0),(-1,-1),'TOP'),('LEFTPADDING',(0,0),(-1,-1),7),('RIGHTPADDING',(0,0),(-1,-1),7),('TOPPADDING',(0,0),(-1,-1),6),('BOTTOMPADDING',(0,0),(-1,-1),6),('LINEBELOW',(0,0),(-1,0),.7,ROSE),('LINEBELOW',(0,1),(-1,-1),.35,LINE),('BACKGROUND',(0,0),(-1,0),C('#F0E8EB'))]))
 return t
story=[]
